import { useEffect, useState } from "react";
import api from "../utils/api";

const Quiz = () => {
  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [quiz, setQuiz] = useState([]);
  const [answers, setAnswers] = useState({});
  const [score, setScore] = useState(null);
  const [loading, setLoading] = useState(false);

  // 🔥 NEW: Timer
  const [timeLeft, setTimeLeft] = useState(60);

  // ================= COURSES =================
  useEffect(() => {
    api.get("/courses")
      .then((res) => setCourses(res.data || []))
      .catch((err) => {
        console.log("Course Error:", err);
        setCourses([]);
      });
  }, []);

  // ================= LOAD QUIZ =================
  useEffect(() => {
    if (!selectedCourse) return;

    setLoading(true);
    setQuiz([]);
    setAnswers({});
    setScore(null);
    setTimeLeft(60); // 🔥 reset timer

    api.get(`/quiz/${selectedCourse}`)
      .then((res) => {
        // 🔥 SHUFFLE QUESTIONS
        const shuffled = (res.data || []).sort(() => Math.random() - 0.5);
        setQuiz(shuffled);
      })
      .catch((err) => {
        console.log("Quiz Error:", err?.response?.data || err);
        alert("Quiz load error (check backend/token)");
        setQuiz([]);
      })
      .finally(() => setLoading(false));
  }, [selectedCourse]);

  // ================= TIMER =================
  useEffect(() => {
    if (!selectedCourse || score !== null) return;

    if (timeLeft === 0) {
      submitQuiz(); // 🔥 auto submit
      return;
    }

    const timer = setTimeout(() => {
      setTimeLeft((prev) => prev - 1);
    }, 1000);

    return () => clearTimeout(timer);
  }, [timeLeft, selectedCourse, score]);

  // ================= SELECT ANSWER =================
  const selectAnswer = (qId, index) => {
    setAnswers((prev) => ({ ...prev, [qId]: index }));
  };

  // ================= SUBMIT =================
  const submitQuiz = async () => {
    if (!selectedCourse) return alert("Select course");
    if (quiz.length === 0) return alert("No quiz available");

    try {
      const res = await api.post(`/quiz/submit/${selectedCourse}`, { answers });
      setScore(res.data.score);
      localStorage.setItem("quizUpdated", Date.now());
    } catch (err) {
      console.log(err?.response?.data || err);
      alert("Submit error");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 py-8">
      <div className="w-full max-w-2xl bg-white shadow-xl rounded-lg p-8 space-y-6 border border-gray-100">
        <h2 className="text-3xl font-extrabold text-blue-700 flex items-center gap-2">
          <span className="inline-block">❓</span> Quiz Section
        </h2>

        {/* COURSE SELECT */}
        <div>
          <label className="block text-gray-700 font-semibold mb-2">Select Course</label>
          <select
            value={selectedCourse}
            onChange={(e) => setSelectedCourse(e.target.value)}
            className="border border-gray-300 p-2 rounded w-full focus:outline-none focus:ring-2 focus:ring-blue-400"
          >
            <option value="">-- Choose a course --</option>
            {courses.map((c) => (
              <option key={c._id} value={c._id}>{c.title}</option>
            ))}
          </select>
        </div>

        {/* TIMER + PROGRESS BAR */}
        {selectedCourse && score === null && (
          <div className="mb-2">
            <div className="flex justify-between items-center mb-1">
              <span className="text-sm font-medium text-blue-700">Time Left</span>
              <span className="text-sm font-bold text-red-500">{timeLeft}s</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-3">
              <div
                className="bg-blue-500 h-3 rounded-full transition-all duration-300"
                style={{ width: `${(timeLeft / 60) * 100}%` }}
              ></div>
            </div>
          </div>
        )}

        {/* LOADING */}
        {loading && (
          <div className="flex items-center gap-2 text-blue-600 font-semibold animate-pulse">
            <svg className="w-5 h-5 animate-spin" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"></path></svg>
            Loading quiz...
          </div>
        )}

        {/* NO QUIZ */}
        {!loading && selectedCourse && quiz.length === 0 && (
          <div className="text-red-500 bg-red-50 border border-red-200 rounded p-3 text-center font-semibold">
            No quiz available for this course.
          </div>
        )}

        {/* QUESTIONS */}
        {!loading && quiz.length > 0 && (
          <div className="space-y-6">
            {quiz.map((q, idx) => (
              <div key={q._id} className="border border-gray-200 p-4 rounded-lg bg-gray-50">
                <div className="mb-2 flex items-center gap-2">
                  <span className="text-lg font-bold text-blue-600">Q{idx + 1}.</span>
                  <span className="font-medium text-gray-800">{q.question}</span>
                </div>
                <div className="space-y-2 mt-2">
                  {q.options.map((opt, i) => (
                    <label key={i} className={`flex items-center gap-2 cursor-pointer p-2 rounded transition ${answers[q._id] === i ? 'bg-blue-100' : ''} ${score !== null ? 'opacity-70' : ''}`}>
                      <input
                        type="radio"
                        name={q._id}
                        checked={answers[q._id] === i}
                        disabled={score !== null}
                        onChange={() => selectAnswer(q._id, i)}
                        className="accent-blue-500"
                      />
                      <span className="text-gray-700">{opt}</span>
                    </label>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* SUBMIT BUTTON */}
        {!loading && quiz.length > 0 && score === null && (
          <div className="flex justify-end">
            <button
              onClick={submitQuiz}
              className="bg-blue-600 hover:bg-blue-700 transition text-white px-6 py-2 rounded-lg font-semibold shadow"
            >
              Submit Quiz
            </button>
          </div>
        )}

        {/* RESULT */}
        {score !== null && (
          <div className="mt-4 p-5 bg-green-50 border border-green-200 rounded-lg text-center">
            <span className="text-2xl">🎉</span>
            <div className="text-lg font-bold text-green-700 mt-2">Your Score: <span className="text-2xl">{score}%</span></div>
            <div className="text-sm text-gray-600 mt-1">Thank you for participating!</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Quiz;

import { useEffect, useState } from "react";
import api from "../utils/api";
import toast from "react-hot-toast";

export default function Admin() {

  const [users, setUsers] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    userId: "",
    title: "",
    instructor: "",
    totalLessons: "",
  });

  const [assignmentForm, setAssignmentForm] = useState({
    title: "",
    description: "",
    course: "",
    dueDate: "",
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const userRes = await api.get("/auth/users");
        setUsers(userRes.data);
        const courseRes = await api.get("/courses/all");
        setCourses(courseRes.data);
      } catch (err) {
        toast.error("Failed to load users/courses");
      }
    };
    fetchData();
  }, []);

  const enroll = async () => {
    if (!form.userId || !form.title) {
      return toast.error("Select user & enter course title");
    }

    try {
      setLoading(true);
      await api.post("/courses/enroll", form);
      toast.success("Course Assigned 🎉");

      setForm({
        userId: "",
        title: "",
        instructor: "",
        totalLessons: "",
      });
    } catch {
      toast.error("Error assigning course");
    } finally {
      setLoading(false);
    }
  };

  const createAssignment = async () => {
    const { title, description, course, dueDate } = assignmentForm;

    if (!title || !description || !course || !dueDate) {
      return toast.error("Fill all assignment fields");
    }

    try {
      setLoading(true);
      await api.post("/assignments", assignmentForm);
      toast.success("Assignment Created ✅");

      setAssignmentForm({
        title: "",
        description: "",
        course: "",
        dueDate: "",
      });
    } catch {
      toast.error("Error creating assignment");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-2 md:px-8">
      <div className="max-w-5xl mx-auto">
        <h2 className="text-3xl font-extrabold text-blue-700 mb-8 flex items-center gap-2">
          <span className="inline-block">👑</span> Admin Panel
        </h2>
        <div className="grid md:grid-cols-2 gap-8">
          {/* Users */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <h3 className="font-bold mb-4 text-lg text-blue-700">Users</h3>
            <div className="divide-y">
              {users.map((u) => (
                <div key={u._id} className="flex justify-between py-2 items-center">
                  <span className="font-medium text-gray-800">{u.name}</span>
                  <button
                    onClick={() => setForm({ ...form, userId: u._id })}
                    className={`px-3 py-1 rounded text-white font-semibold ${form.userId === u._id ? 'bg-blue-700' : 'bg-blue-500 hover:bg-blue-600'}`}
                  >
                    {form.userId === u._id ? "Selected" : "Select"}
                  </button>
                </div>
              ))}
            </div>
          </div>

          {/* Assign Course */}
          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100">
            <h3 className="font-bold mb-4 text-lg text-blue-700">Assign Course</h3>
            <input
              placeholder="Course Title"
              className="w-full border p-2 mb-2 rounded"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
            />
            <input
              placeholder="Instructor"
              className="w-full border p-2 mb-2 rounded"
              value={form.instructor}
              onChange={(e) => setForm({ ...form, instructor: e.target.value })}
            />
            <input
              placeholder="Total Lessons"
              className="w-full border p-2 mb-2 rounded"
              value={form.totalLessons}
              onChange={(e) => setForm({ ...form, totalLessons: e.target.value })}
            />
            <button
              onClick={enroll}
              disabled={loading}
              className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 rounded-lg font-semibold mt-2"
            >
              {loading ? "Processing..." : "Assign Course"}
            </button>
          </div>
        </div>

        {/* Assignment Section */}
        <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-100 mt-10">
          <h3 className="font-bold mb-4 text-lg text-green-700">Create Assignment</h3>
          <div className="grid md:grid-cols-2 gap-4">
            <input
              placeholder="Title"
              value={assignmentForm.title}
              className="w-full border p-2 mb-2 rounded"
              onChange={(e) => setAssignmentForm({ ...assignmentForm, title: e.target.value })}
            />
            <input
              type="date"
              value={assignmentForm.dueDate}
              className="w-full border p-2 mb-2 rounded"
              onChange={(e) => setAssignmentForm({ ...assignmentForm, dueDate: e.target.value })}
            />
            <select
              value={assignmentForm.course}
              className="w-full border p-2 mb-2 rounded"
              onChange={(e) => setAssignmentForm({ ...assignmentForm, course: e.target.value })}
            >
              <option value="">Select Course</option>
              {courses.map((c) => (
                <option key={c._id} value={c._id}>{c.title}</option>
              ))}
            </select>
            <textarea
              placeholder="Description"
              value={assignmentForm.description}
              className="w-full border p-2 mb-2 rounded md:col-span-2"
              onChange={(e) => setAssignmentForm({ ...assignmentForm, description: e.target.value })}
              rows={2}
            />
          </div>
          <button
            onClick={createAssignment}
            disabled={loading}
            className="w-full bg-green-600 hover:bg-green-700 text-white py-2 rounded-lg font-semibold mt-2"
          >
            {loading ? "Creating..." : "Create Assignment"}
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import api from "../utils/api";
import toast from "react-hot-toast";

export default function AdminCourses() {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(false);

  // ================= FETCH =================
  const fetchCourses = async () => {
    try {
      const res = await api.get("/courses/all");
      setCourses(res.data || []);
    } catch {
      toast.error("Failed to load courses");
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  // ================= REMOVE USER =================
  const removeUser = async (courseId, userId) => {
    try {
      setLoading(true);

      await api.post("/courses/remove-user", {
        courseId,
        userId,
      });

      toast.success("User removed");

      fetchCourses(); // 🔥 refresh

    } catch {
      toast.error("Remove failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 space-y-6">

      <h2 className="text-3xl font-bold">
        📚 Course Management
      </h2>

      {courses.length === 0 && (
        <p>No courses found</p>
      )}

      {courses.map((course) => (
        <div
          key={course._id}
          className="bg-white p-5 rounded-xl shadow"
        >
          <h3 className="text-xl font-bold">
            {course.title}
          </h3>

          <p className="text-gray-500 mb-3">
            Instructor: {course.instructor || "N/A"}
          </p>

          {/* USERS */}
          <div>
            <h4 className="font-semibold mb-2">
              Enrolled Users:
            </h4>

            {course.users?.length === 0 && (
              <p className="text-gray-400">
                No users enrolled
              </p>
            )}

            {course.users?.map((u) => (
              <div
                key={u._id}
                className="flex justify-between items-center border-b py-2"
              >
                <span>{u.name}</span>

                <button
                  onClick={() =>
                    removeUser(course._id, u._id)
                  }
                  className="text-red-500"
                >
                  Remove
                </button>
              </div>
            ))}
          </div>

        </div>
      ))}
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { motion } from "framer-motion";
import { AreaChart, Area, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, Legend } from "recharts";
import api from "../utils/api";
import toast from "react-hot-toast";

const Stat = ({ label, value, hint, gradient }) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.25 }}
      className={`rounded-2xl shadow-sm ring-1 ring-black/5 p-5 bg-white dark:bg-gray-900`}
    >
      <div className="flex items-start justify-between gap-4">
        <div>
          <p className="text-sm text-gray-500 dark:text-gray-400 font-semibold">{label}</p>
          <p className={`text-2xl font-extrabold ${gradient}`}>{value}</p>
          {hint ? <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">{hint}</p> : null}
        </div>
        <div className="h-10 w-10 rounded-xl bg-gray-50 dark:bg-gray-800 flex items-center justify-center">
          <div className={`h-2.5 w-2.5 rounded-full ${gradient}`} />
        </div>
      </div>
