import React, { useState, useEffect } from 'react';
import apiService from '../../services/api';

const TeacherAnalytics = () => {
  const [analytics, setAnalytics] = useState({
    totalStudents: 0,
    totalCourses: 0,
    totalAssignments: 0,
    averageGrade: 0,
    recentActivity: []
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [timeRange, setTimeRange] = useState('month'); // week, month, year

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        // This would need to be implemented in the backend
        // For now, showing placeholder data
        setAnalytics({
          totalStudents: 45,
          totalCourses: 8,
          totalAssignments: 24,
          averageGrade: 87.5,
          recentActivity: [
            { type: 'assignment_submission', message: 'Alice submitted JavaScript Assignment', time: '2 hours ago' },
            { type: 'course_enrollment', message: 'Bob enrolled in React Basics', time: '4 hours ago' },
            { type: 'question_posted', message: 'Carol posted a question in Node.js forum', time: '6 hours ago' },
            { type: 'grade_posted', message: 'David graded HTML/CSS quiz', time: '1 day ago' }
          ]
        });
      } catch (err) {
        setError(err.response?.data?.message || 'Failed to load analytics');
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, [timeRange]);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
          Analytics Dashboard
        </h1>
        <p className="text-gray-600 dark:text-gray-400">
          Track your teaching performance and student engagement.
        </p>
      </div>

      {/* Time Range Selector */}
      <div className="flex space-x-4 mb-6">
        {['week', 'month', 'year'].map((range) => (
          <button
            key={range}
            onClick={() => setTimeRange(range)}
            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
              timeRange === range
